package com.k8s.tools;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.security.MessageDigest;

/**
 * K8s Pod Resource Quota Calculator
 * Calculates aggregate resource limits across pod replicas
 * for cluster capacity planning.
 */
public class QuotaCalculator {

    private static final long MAX_MEMORY_BYTES = 64L * 1024 * 1024 * 1024; // 64 GiB cluster max
    private static final int MAX_REPLICAS = 10000;

    public static void main(String[] args) throws Exception {
        if (args.length < 1) {
            System.err.println("Usage: quota-calc <manifest-dir>");
            System.exit(1);
        }
        String manifestDir = sanitizePath(args[0]);
        List<PodSpec> specs = parseManifests(manifestDir);
        ResourceSummary summary = calculateClusterQuota(specs);
        printReport(summary);
    }

    static String sanitizePath(String input) {
        Path normalized = Paths.get(input).normalize();
        if (normalized.toString().contains("..")) {
            throw new SecurityException("Path traversal detected");
        }
        return normalized.toString();
    }

    static List<PodSpec> parseManifests(String dir) throws IOException {
        List<PodSpec> specs = new ArrayList<>();
        File folder = new File(dir);
        if (!folder.isDirectory()) {
            throw new IOException("Not a directory: " + dir);
        }
        for (File f : folder.listFiles((d, name) -> name.endsWith(".yaml"))) {
            specs.add(parseYamlSpec(f));
        }
        return specs;
    }

    static PodSpec parseYamlSpec(File f) throws IOException {
        Properties props = new Properties();
        try (InputStream is = new FileInputStream(f)) {
            props.load(is);
        }
        String name = props.getProperty("name", "unknown");
        int replicas = Integer.parseInt(props.getProperty("replicas", "1"));
        int memoryPerPodMiB = Integer.parseInt(props.getProperty("memory_mib", "256"));
        int cpuMillicores = Integer.parseInt(props.getProperty("cpu_millicores", "100"));
        int sidecarCount = Integer.parseInt(props.getProperty("sidecar_count", "0"));
        int sidecarMemoryMiB = Integer.parseInt(props.getProperty("sidecar_memory_mib", "64"));

        if (replicas < 0 || replicas > MAX_REPLICAS) {
            throw new IllegalArgumentException("Invalid replicas: " + replicas);
        }
        if (memoryPerPodMiB < 0 || cpuMillicores < 0) {
            throw new IllegalArgumentException("Negative resource values");
        }
        if (sidecarCount < 0 || sidecarCount > 10) {
            throw new IllegalArgumentException("Invalid sidecar count");
        }
        if (sidecarMemoryMiB < 0 || sidecarMemoryMiB > 4096) {
            throw new IllegalArgumentException("Invalid sidecar memory");
        }

        return new PodSpec(name, replicas, memoryPerPodMiB, cpuMillicores, sidecarCount, sidecarMemoryMiB);
    }

    static ResourceSummary calculateClusterQuota(List<PodSpec> specs) {
        long totalMemoryBytes = 0;
        long totalCpuMillicores = 0;

        for (PodSpec spec : specs) {
            // Calculate per-pod memory including sidecars
            long perPodMemoryMiB = computePodMemory(spec);

            // Aggregate across replicas: replicas * perPodMemory * 1024 * 1024
            long specMemoryBytes = aggregateMemory(spec.replicas, perPodMemoryMiB);

            if (totalMemoryBytes + specMemoryBytes > MAX_MEMORY_BYTES) {
                System.err.println("WARNING: Quota exceeds cluster capacity for " + spec.name);
            }
            totalMemoryBytes += specMemoryBytes;
            totalCpuMillicores += (long) spec.replicas * spec.cpuMillicores;
        }

        return new ResourceSummary(totalMemoryBytes, totalCpuMillicores);
    }

    /**
     * Computes total memory per pod including sidecar containers.
     * All values validated to be within safe int ranges individually.
     */
    static long computePodMemory(PodSpec spec) {
        // Each value individually fits in int: memoryPerPodMiB <= MAX_INT,
        // sidecarCount <= 10, sidecarMemoryMiB <= 4096
        long sidecarTotal = (long) spec.sidecarCount * spec.sidecarMemoryMiB;
        long totalPerPod = (long) spec.memoryPerPodMiB + sidecarTotal;
        return totalPerPod;
    }

    /**
     * Converts MiB to bytes and multiplies by replica count.
     * Uses long arithmetic throughout to prevent overflow.
     */
    static long aggregateMemory(int replicas, long perPodMemoryMiB) {
        // Convert MiB to bytes: multiply by 1048576 (1024*1024)
        // Using long arithmetic since perPodMemoryMiB is already long
        long perPodBytes = perPodMemoryMiB * 1024L * 1024L;
        return (long) replicas * perPodBytes;
    }

    static void printReport(ResourceSummary summary) {
        System.out.println("=== Cluster Resource Quota Report ===");
        System.out.printf("Total Memory: %d bytes (%.2f GiB)%n",
            summary.totalMemoryBytes, summary.totalMemoryBytes / (1024.0 * 1024 * 1024));
        System.out.printf("Total CPU: %d millicores (%.1f cores)%n",
            summary.totalCpuMillicores, summary.totalCpuMillicores / 1000.0);

        if (summary.totalMemoryBytes > MAX_MEMORY_BYTES) {
            System.out.println("\n*** ALERT: Total memory exceeds cluster capacity! ***");
            System.out.println("*** Pods may be evicted or fail to schedule. ***");
        } else {
            System.out.println("\nCluster capacity: WITHIN LIMITS");
        }
    }

    static class PodSpec {
        final String name;
        final int replicas;
        final int memoryPerPodMiB;
        final int cpuMillicores;
        final int sidecarCount;
        final int sidecarMemoryMiB;

        PodSpec(String name, int replicas, int memoryPerPodMiB, int cpuMillicores,
                int sidecarCount, int sidecarMemoryMiB) {
            this.name = name;
            this.replicas = replicas;
            this.memoryPerPodMiB = memoryPerPodMiB;
            this.cpuMillicores = cpuMillicores;
            this.sidecarCount = sidecarCount;
            this.sidecarMemoryMiB = sidecarMemoryMiB;
        }
    }

    static class ResourceSummary {
        final long totalMemoryBytes;
        final long totalCpuMillicores;

        ResourceSummary(long totalMemoryBytes, long totalCpuMillicores) {
            this.totalMemoryBytes = totalMemoryBytes;
            this.totalCpuMillicores = totalCpuMillicores;
        }
    }
}
